const listPurchaseTransactions = `-- name: ListPurchaseTransactions :many
SELECT t.id, t.administration_id, t.financial_account_id, t.purchase_transaction_batch_id, t.payable_type, t.payable_id, t.contact_id, t.amount, t.date, t.description, t.end_to_end_id, t.sepa_iban, t.sepa_iban_account_name, t.sepa_bic, t.source_sepa_iban, t.source_sepa_iban_account_name, t.cancelled, t.created_at, t.updated_at, coalesce(d.state = 'paid', false)::boolean AS payable_paid, count(*) OVER () AS total
FROM purchase_transactions t
LEFT JOIN purchase_documents d ON d.id = t.payable_id
WHERE t.administration_id = $1
  AND (cardinality($2::text[]) = 0 OR
       (CASE WHEN t.cancelled THEN 'cancelled'
             WHEN d.state = 'paid' THEN 'paid'
             WHEN t.purchase_transaction_batch_id IS NOT NULL THEN 'pending_payment'
             ELSE 'open' END) = ANY($2::text[]))
  AND ($3::date IS NULL OR t.date >= $3)
  AND ($4::date IS NULL OR t.date <= $4)
  AND (NOT $5::boolean OR t.purchase_transaction_batch_id IS NULL)
  AND ($6::bigint IS NULL OR t.purchase_transaction_batch_id = $6)
  AND ($7::bigint IS NULL OR t.payable_id = $7)
ORDER BY t.created_at, t.id
LIMIT $9 OFFSET $8
`

