const purchaseTotals = `-- name: PurchaseTotals :one
SELECT (count(*) FILTER (WHERE d.state = 'open'))::int AS pay_count,
       coalesce(sum((CASE WHEN d.revenue_invoice THEN -d.total_incl_tax ELSE d.total_incl_tax END)
                    - coalesce((SELECT sum(p.price) FROM payments p WHERE p.invoice_type = 'Document' AND p.invoice_id = d.id), 0))
                FILTER (WHERE d.state = 'open'), 0)::bigint AS pay_amount,
       ((count(*) FILTER (WHERE d.state = 'new'))
        + (SELECT count(*) FROM typeless_documents t WHERE t.administration_id = $1::bigint))::int AS process_count
FROM purchase_documents d
WHERE d.administration_id = $1::bigint
`

type PurchaseTotalsRow struct {
	PayCount     int32
	PayAmount    int64
	ProcessCount int32
}

// What open purchase invoices and receipts have unpaid, and how many
// uploads wait to be processed.
func (q *Queries) PurchaseTotals(ctx context.Context, admin int64) (PurchaseTotalsRow, error) {
	row := q.db.QueryRow(ctx, purchaseTotals, admin)
	var i PurchaseTotalsRow
	err := row.Scan(&i.PayCount, &i.PayAmount, &i.ProcessCount)
	return i, err
}

